override fun jsonExists(
    expression: Expression<*>,
    vararg path: String,
    optional: String?,
    jsonType: IColumnType<*>,
    queryBuilder: QueryBuilder
) {
    val transaction = TransactionManager.current()
    if (path.size > 1) {
        transaction.throwUnsupportedException("SQLite does not support multiple JSON path arguments")
    }
    optional?.let {
        transaction.throwUnsupportedException("SQLite does not support optional arguments other than a path argument")
    }
    queryBuilder {
        append("JSON_TYPE(", expression, ", ")
        append("'$", path.firstOrNull() ?: "", "'")
        append(") IS NOT NULL")
    }
}

override fun <T> jsonExtract(
    expression: Expression<T>,
    vararg path: String,
    toScalar: Boolean,
    jsonType: IColumnType<*>,
    queryBuilder: QueryBuilder
) = queryBuilder {
    if (toScalar) append("JSON_UNQUOTE(")
    append("JSON_EXTRACT(", expression, ", ")
    path.ifEmpty { arrayOf("") }.appendTo { +"\"$$it\"" }
    append(")${if (toScalar) ")" else ""}")
}

override fun jsonContains(
    target: Expression<*>,
    candidate: Expression<*>,
    path: String?,
    jsonType: IColumnType<*>,
    queryBuilder: QueryBuilder
) = queryBuilder {
    append("JSON_CONTAINS(", target, ", ", candidate)
    path?.let {
        append(", '$$it'")
    }
    append(")")
}

override fun jsonExists(
    expression: Expression<*>,
    vararg path: String,
    optional: String?,
    jsonType: IColumnType<*>,
    queryBuilder: QueryBuilder
) {
    val oneOrAll = optional?.lowercase()
    if (oneOrAll != "one" && oneOrAll != "all") {
        TransactionManager.current().throwUnsupportedException("MySQL requires a single optional argument: 'one' or 'all'")
    }
    queryBuilder {
        append("JSON_CONTAINS_PATH(", expression, ", ")
        append("'$oneOrAll', ")
        path.ifEmpty { arrayOf("") }.appendTo { +"'$$it'" }
        append(")")
    }
}

override fun <T> jsonExtract(
    expression: Expression<T>,
    vararg path: String,
    toScalar: Boolean,
    jsonType: IColumnType<*>,
    queryBuilder: QueryBuilder
) = queryBuilder {
    append("${jsonType.sqlType()}_EXTRACT_PATH")
    if (toScalar) append("_TEXT")
    append("(", expression, ", ")
    path.ifEmpty { arrayOf("$") }.appendTo { + "'$it'" }
    append(")")
}

override fun jsonExists(
    expression: Expression<*>,
    vararg path: String,
    optional: String?,
    jsonType: IColumnType<*>,
    queryBuilder: QueryBuilder
) {
    if (path.size > 1) {
        TransactionManager.current().throwUnsupportedException("PostgreSQL does not support multiple JSON path arguments")
    }
    val isNotJsonB = !(jsonType as JsonColumnMarker).usesBinaryFormat
    queryBuilder {
        append("JSONB_PATH_EXISTS(")
        if (isNotJsonB) {
            append("CAST(", expression, " as jsonb), ")
        } else {
            append(expression, ", ")
        }
        append("'$", path.firstOrNull() ?: "", "'")
        optional?.let {
            append(", '$it'")
        }
        append(")")
    }
}

open class ExplainQuery(
    val analyze: Boolean,
    val options: String?,
    private val internalStatement: Statement<*>
) : Iterable<ExplainResultRow>, Statement<ResultSet>(StatementType.SHOW, emptyList()) {
    private val transaction
        get() = TransactionManager.current()

    override fun PreparedStatementApi.executeInternal(transaction: Transaction): ResultSet = executeQuery()

    override fun arguments(): Iterable<Iterable<Pair<IColumnType<*>, Any?>>> = internalStatement.arguments()

    override fun prepareSQL(transaction: Transaction, prepared: Boolean): String {
        val internalSql = internalStatement.prepareSQL(transaction, prepared)
        return transaction.db.dialect.functionProvider.explain(analyze, options, internalSql, transaction)
    }
